@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@activeChannelName"
                 ChannelDescription="@activeChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnLoadMore="LoadOlderMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (threadOpen && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message> threadReplies = [];

    private int activeChannelId;
    private string activeChannelName = "";
    private string activeChannelDescription = "";

    private bool threadOpen;
    private Message? threadRootMessage;

    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannelId = channel.Id;
        activeChannelName = channel.Name;
        activeChannelDescription = channel.Description;
        hasMoreMessages = true;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;

        messages.InsertRange(0, older);
        BuildThreadSummaries();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        UpdateThreadSummary(threadRootMessage.Id);
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to reflect updated reactions
        messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
    }

    private void BuildThreadSummaries()
    {
        // Build summaries from messages that have replies
        var replyGroups = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value);

        threadSummaries = replyGroups.Select(g => new ThreadSummary(
            g.Key,
            g.Count(),
            g.Max(m => m.SentAt)
        )).ToList();
    }

    private void UpdateThreadSummary(int rootMessageId)
    {
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == rootMessageId);
        var summary = new ThreadSummary(rootMessageId, threadReplies.Count, DateTime.Now);
        if (existing >= 0)
            threadSummaries[existing] = summary;
        else
            threadSummaries.Add(summary);
    }
}

