toolArgs.file_text:
/* Chat Layout */
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
.channel-sidebar {
    background: #2b2d42;
    color: #edf2f4;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 1rem;
    margin: 0;
    font-size: 1.1rem;
    border-bottom: 1px solid #3d3f56;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.6rem 1rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #3d3f56;
}

.channel-item.active {
    background: #3d3f56;
    border-left-color: #8d99ae;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #8d99ae;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 0.6rem;
    right: 0.75rem;
    background: #ef233c;
    color: white;
    border-radius: 10px;
    padding: 1px 7px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #f8f9fa;
}

.message-area-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #dee2e6;
    background: white;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

.message-area-header p {
    margin: 0.2rem 0 0;
    font-size: 0.8rem;
    color: #6c757d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #6c757d;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #e9ecef;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.72rem;
    color: #6c757d;
}

.message-content {
    margin-top: 0.2rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

.reaction-row {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.78rem;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #dee2e6;
}

.thread-link {
    background: none;
    border: none;
    color: #0d6efd;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.25rem;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message Actions (on hover) */
.message-actions {
    position: absolute;
    top: 0.25rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.08);
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 2px 4px;
    border-radius: 3px;
}

.action-btn:hover {
    background: #e9ecef;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.4rem;
    display: flex;
    gap: 0.25rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #e9ecef;
}

/* Message Input */
.message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border-top: 1px solid #dee2e6;
    background: white;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input textarea:focus {
    border-color: #86b7fe;
    box-shadow: 0 0 0 2px rgba(13,110,253,0.15);
}

.send-button {
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-button:hover:not(:disabled) {
    background: #0b5ed7;
}

.send-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-left: 1px solid #dee2e6;
    background: white;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #6c757d;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #e9ecef;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #495057;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
    border-bottom: 1px solid #f1f3f5;
}

.thread-reply:last-child {
    border-bottom: none;
}

